export const code = async (inputs) => {
  const payload = typeof inputs.payload === 'string' ? JSON.parse(inputs.payload) : (inputs.payload || {});
  const packages = payload.packages || [];
  const students = payload.students || [];
  const alreadyReminded = payload.alreadyReminded || [];

  const studentMap = {};
  students.forEach(s => { studentMap[s.id] = s; });

  const emails = [];
  const skipped = [];

  packages.forEach(p => {
    const pending = (p.amount || p.finalAmount || 0) - (p.amountReceived || 0);
    if (pending <= 0) {
      skipped.push({ packageId: p.id, reason: 'fully_paid' });
      return;
    }
    const student = studentMap[p.studentId];
    if (!student || !student.guardianEmail) {
      skipped.push({ packageId: p.id, studentId: p.studentId, reason: 'missing_email' });
      return;
    }
    if (alreadyReminded.includes(p.id)) {
      skipped.push({ packageId: p.id, reason: 'already_reminded' });
      return;
    }
    const hasUrl = !!p.paymentUrl;
    const urlLine = hasUrl
      ? `Payment Link: ${p.paymentUrl}`
      : 'Payment link is not yet configured. Please contact the academy for payment details.';

    emails.push({
      studentId: p.studentId,
      studentName: student.name || 'Student',
      guardianEmail: student.guardianEmail,
      program: p.program || 'Enrollment',
      pendingAmount: pending,
      subject: `Payment Reminder — ${student.name}`,
      body: `Dear Parent/Guardian,

This is a reminder that a payment is currently pending for ${student.name}.

Enrollment: ${p.program || 'Enrollment'}
Pending Amount: Rs. ${pending.toLocaleString('en-IN')}

${urlLine}

Regards,
Tennis Academy Management`
    });
  });

  return { emails, skipped, pendingCount: emails.length, skippedCount: skipped.length };
};
